167				})
168				if !errors.Is(err, ErrConflict) {
169					t.Fatalf("want ErrConflict, got %v", err)
170				}
171				for _, want := range []string{"LEAF", c.wantInit, c.wantRemain, "0.000", c.wantGap} {
172					if !strings.Contains(err.Error(), want) {
173						t.Fatalf("错误说明应包含 %q: %v", want, err)
174					}
175				}
176				assertStillOpenAndUndestroyed(t, path, "LEAF", c.wantRemain, nil)
177			})
178		}
179	}
