181	// TestDestroyRejectsGapWithMultipleChildren 多份直接子样按创建时初始量
182	// 累加：C1 4.000 + C2 2.000 = 直接分出总量 6.000，加剩余 3.000 合计
183	// 9.000，距初始 10.000 缺 1.000；错误说明列出剩余 3.000、直接分出总量
184	// 6.000、合计 9.000 与缺口 1.000。
185	func TestDestroyRejectsGapWithMultipleChildren(t *testing.T) {
186		l := &ledger{
187			Samples: map[string]*sampleRecord{
188				"P":  withChild(activeSample("P", "", 10000, 3000), "C1", "C2"),
189				"C1": plainChild("C1", "P", 4000, 4000),
190				"C2": plainChild("C2", "P", 2000, 2000),
191			},
192		}
193		s, path := openGapLedger(t, l)
194		_, err := s.Destroy(DestroyInput{
195			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
196		})
197		if !errors.Is(err, ErrConflict) {
198			t.Fatalf("want ErrConflict, got %v", err)
199		}
200		for _, want := range []string{"P", "10.000", "3.000", "6.000", "9.000", "1.000"} {
201			if !strings.Contains(err.Error(), want) {
202				t.Fatalf("错误说明应包含 %q: %v", want, err)
203			}
204		}
205		assertStillOpenAndUndestroyed(t, path, "P", "3.000", []string{"C1", "C2"})
206	}
207	
208	// TestDestroyConservationUsesChildInitialOnly 核对只认各直接子样创建时
209	// 取得的初始量：
210	//   - 子样后来继续分装、当前只剩 1.000，父样有缺口时仍按子样初始 4.000
211	//     计缺口（5.000+4.000=9.000，缺 1.000），不能改用子样当前剩余量；
212	//   - 孙样不重复计入，也不替父样凑数；
213	//   - 数量恰好守恒时（6.000+4.000=10.000），即使子样已把自己的量继续
214	//     分出或独立销毁，父样仍正常销毁 6.000，重开后可查询。
215	func TestDestroyConservationUsesChildInitialOnly(t *testing.T) {
216		// 场景一：子样 C 自身又分出 3.000 给孙样 G、当前只剩 1.000；父样剩余
217		// 5.000 有 1.000 缺口。直接分出总量必须仍显示 4.000、缺口 1.000。
218		childSplit := plainChild("C", "P", 4000, 1000)
219		childSplit.Children = []string{"G"}
220		childSplit.History = append(childSplit.History, historyRecord{
221			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
222		})
223		bad := &ledger{
224			Samples: map[string]*sampleRecord{
225				"P": withChild(activeSample("P", "", 10000, 5000), "C"),
226				"C": childSplit,
227				"G": plainChild("G", "C", 3000, 3000),
228			},
229		}
230		s, path := openGapLedger(t, bad)
231		_, err := s.Destroy(DestroyInput{
232			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
233		})
234		if !errors.Is(err, ErrConflict) {
235			t.Fatalf("按子样当前剩余量会误判缺口，仍应按其创建初始量拒绝: %v", err)
236		}
237		for _, want := range []string{"P", "5.000", "4.000", "1.000"} {
238			if !strings.Contains(err.Error(), want) {
239				t.Fatalf("错误说明应包含 %q（按子样创建初始量核对）: %v", want, err)
240			}
241		}
242		assertStillOpenAndUndestroyed(t, path, "P", "5.000", []string{"C"})
243	
244		// 场景二：父样剩余 6.000 恰好守恒，子样已分装用尽（无销毁信息）、
245		// 孙样持有全部 4.000；父样销毁成功，销毁量 6.000，重开可查询。
246		childExhausted := plainChild("C", "P", 4000, 0)
247		childExhausted.Children = []string{"G"}
248		childExhausted.History = append(childExhausted.History, historyRecord{
249			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
250		})
251		good1 := &ledger{
252			Samples: map[string]*sampleRecord{
253				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
254				"C": childExhausted,
255				"G": plainChild("G", "C", 4000, 4000),
256			},
257		}
258		s1, path1 := openGapLedger(t, good1)
259		view, err := s1.Destroy(DestroyInput{
260			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
261		})
262		if err != nil {
263			t.Fatalf("孙样不重复计入，6.000+4.000=10.000 应销毁成功: %v", err)
264		}
265		if view.Destruction == nil || view.Destruction.Qty != "6.000" || view.Remaining != "0.000" {
266			t.Fatalf("父样销毁视图错误: %+v", view)
267		}
268		reopened, err := Open(path1)
269		if err != nil {
270			t.Fatalf("守恒销毁后的文件必须仍能重新打开（这正是修复点）: %v", err)
271		}
272		p, _ := reopened.GetSample("P")
273		if p.Destruction == nil || p.Destruction.Qty != "6.000" || p.Remaining != "0.000" {
274			t.Fatalf("重开后销毁记录应保留真实销毁量 6.000: %+v", p)
275		}
276	
277		// 场景三：子样 C 已独立销毁 3.000（另分出 1.000 给孙样），父样仍按
278		// 子样创建初始量 4.000 核对，6.000+4.000=10.000 销毁成功。
279		childDestroyed := destroyedSampleWithParent("C", "P", 4000, 3000)
280		childDestroyed.Children = []string{"G"}
281		good2 := &ledger{
282			Samples: map[string]*sampleRecord{
283				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
284				"C": childDestroyed,
285				"G": plainChild("G", "C", 1000, 1000),
286			},
287		}
288		s2, path2 := openGapLedger(t, good2)
289		if _, err := s2.Destroy(DestroyInput{
290			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
291		}); err != nil {
292			t.Fatalf("子样后来销毁不改变父样已分出量，数量守恒应销毁成功: %v", err)
293		}
294		reopened2, err := Open(path2)
295		if err != nil {
296			t.Fatalf("父子各自销毁的守恒文件应正常重开: %v", err)
297		}
298		p2, _ := reopened2.GetSample("P")
299		c2, _ := reopened2.GetSample("C")
300		if p2.Destruction == nil || p2.Destruction.Qty != "6.000" {
301			t.Fatalf("父样销毁量应为 6.000: %+v", p2.Destruction)
302		}
303		if c2.Destruction == nil || c2.Destruction.Qty != "3.000" {
304			t.Fatalf("子样销毁记录应独立保留 3.000: %+v", c2.Destruction)
305		}
306	}
307	
308	// TestDestroyConservationForSplitChildUsesOwnInitial 分装子样申请销毁时按
309	// 它自身创建时取得的初始量核对：自身初始 4.000、已直接分出 1.000、剩余
310	// 2.000 时有 1.000 缺口必须拒绝；父样 P 的数量不参与本次核对，也不被
311	// 改动。数量恰好守恒（剩余 3.000 + 孙样 1.000 = 4.000）时正常销毁。
312	func TestDestroyConservationForSplitChildUsesOwnInitial(t *testing.T) {
313		// 缺口分支：P 自身守恒（6.000 + C 的 4.000 = 10.000），不替 C 凑数。
314		bad := &ledger{
315			Samples: map[string]*sampleRecord{
316				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
317				"C": withChild(plainChild("C", "P", 4000, 2000), "G"),
318				"G": plainChild("G", "C", 1000, 1000),
319			},
320		}
321		s, path := openGapLedger(t, bad)
322		view, err := s.Destroy(DestroyInput{
323			SampleID: "C", Operator: "李四", Location: "实验室B",
324			At: destroyGapAt, Reason: "r",
325		})
326		if err == nil {
327			t.Fatalf("子样数量有缺口时必须拒绝销毁: %+v", view)
328		}
329		if !errors.Is(err, ErrConflict) {
330			t.Fatalf("want ErrConflict, got %v", err)
331		}
332		for _, want := range []string{"C", "4.000", "2.000", "1.000"} {
333			if !strings.Contains(err.Error(), want) {
334				t.Fatalf("错误说明应包含 %q: %v", want, err)
335			}
336		}
337		// 父样与子样都保持原样，文件仍可重开。
338		p, _ := s.GetSample("P")
339		if p.Remaining != "6.000" || p.Destruction != nil {
340			t.Fatalf("拒绝销毁子样不应改动父样: %+v", p)
341		}
342		assertStillOpenAndUndestroyed(t, path, "C", "2.000", []string{"G"})
343	
344		// 守恒分支：C 剩余 3.000 + G 1.000 = 自身初始 4.000，销毁 3.000。
345		good := &ledger{
346			Samples: map[string]*sampleRecord{
347				"P": withChild(activeSample("P", "", 10000, 6000), "C"),
348				"C": withChild(plainChild("C", "P", 4000, 3000), "G"),
349				"G": plainChild("G", "C", 1000, 1000),
350			},
351		}
352		s2, path2 := openGapLedger(t, good)
353		cView, err := s2.Destroy(DestroyInput{
354			SampleID: "C", Operator: "李四", Location: "实验室B",
355			At: destroyGapAt, Reason: "r",
356		})
357		if err != nil {
358			t.Fatalf("子样数量守恒应销毁成功: %v", err)
359		}
360		if cView.Destruction == nil || cView.Destruction.Qty != "3.000" || cView.Remaining != "0.000" {
361			t.Fatalf("子样销毁视图错误: %+v", cView)
362		}
363		reopened, err := Open(path2)
364		if err != nil {
365			t.Fatalf("守恒销毁后的文件应正常重开: %v", err)
366		}
367		c3, _ := reopened.GetSample("C")
368		if c3.Destruction == nil || c3.Destruction.Qty != "3.000" {
369			t.Fatalf("重开后子样销毁记录应保留 3.000: %+v", c3)
370		}
371	}
372	
373	// TestDestroyConservationIndependentAcrossRoots 其他原样与兄弟子样不参与
374	// 核对：P 守恒时即使另一份原样 Q 有缺口，P 仍能销毁；Q 的销毁被拒绝。
375	func TestDestroyConservationIndependentAcrossRoots(t *testing.T) {
376		l := &ledger{
377			Samples: map[string]*sampleRecord{
378				"P":   withChild(activeSample("P", "", 10000, 6000), "P-C"),
379				"P-C": plainChild("P-C", "P", 4000, 4000),
380				"Q":   activeSample("Q", "", 5000, 1000),
381			},
382		}
383		s, path := openGapLedger(t, l)
384	
385		// P 数量恰好守恒，正常销毁。
386		pView, err := s.Destroy(DestroyInput{
387			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
388		})
389		if err != nil {
390			t.Fatalf("P 数量守恒不应受 Q 的缺口影响: %v", err)
391		}
392		if pView.Destruction == nil || pView.Destruction.Qty != "6.000" {
393			t.Fatalf("P 应销毁 6.000: %+v", pView)
394		}
395	
396		// Q 缺 4.000（无直接子样，剩余 1.000 != 初始 5.000），拒绝。
397		qView, err := s.Destroy(DestroyInput{
398			SampleID: "Q", Operator: "h", Location: "l",
399			At: destroyGapAt.Add(time.Hour), Reason: "r",
400		})
401		if err == nil {
402			t.Fatalf("Q 数量有缺口必须拒绝: %+v", qView)
403		}
404		if !errors.Is(err, ErrConflict) || !strings.Contains(err.Error(), "4.000") {
405			t.Fatalf("Q 的缺口应为 4.000 且返回 ErrConflict: %v", err)
406		}
407		q, _ := s.GetSample("Q")
408		if q.Destruction != nil || q.Remaining != "1.000" {
409			t.Fatalf("Q 应保持未销毁、剩余 1.000: %+v", q)
410		}
411	
412		// 文件仍可重开：P 带真实销毁量 6.000，Q 仍是未销毁旧记录。
413		s2, err := Open(path)
414		if err != nil {
415			t.Fatalf("部分销毁成功、部分旧记录保留的文件应正常重开: %v", err)
416		}
417		p2, _ := s2.GetSample("P")
418		q2, _ := s2.GetSample("Q")
419		if p2.Destruction == nil || p2.Destruction.Qty != "6.000" || p2.Remaining != "0.000" {
420			t.Fatalf("P 销毁记录应保留: %+v", p2)
421		}
422		if q2.Destruction != nil || q2.Remaining != "1.000" {
423			t.Fatalf("Q 应仍是可查询的未销毁旧记录: %+v", q2)
424		}
425	}
426	
427	// TestDestroyExactConservationViaPublicAPI 端到端合法流程：公开操作产生
428	// 的记录始终恰好守恒，初始 10.000、分出 4.000 后销毁剩余 6.000 成功，
429	// 重开后销毁记录可查询。
430	func TestDestroyExactConservationViaPublicAPI(t *testing.T) {
431		dir := t.TempDir()
432		path := filepath.Join(dir, "exact.json")
433		s, err := Open(path)
434		if err != nil {
435			t.Fatal(err)
436		}
437		s.now = func() time.Time { return registerCheckAt }
438		mustRegister(t, s, "P", "10.000", "张三", "A")
439		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
440			{ID: "C", Qty: "4.000"},
441		}}); err != nil {
442			t.Fatal(err)
443		}
444		view, err := s.Destroy(DestroyInput{
445			SampleID: "P", Operator: "张三", Location: "A", At: destroyGapAt, Reason: "r",
446		})
447		if err != nil {
448			t.Fatalf("公开操作产生的守恒记录应正常销毁: %v", err)
449		}
450		if view.Destruction.Qty != "6.000" || view.Remaining != "0.000" {
451			t.Fatalf("应销毁真实剩余 6.000: %+v", view)
452		}
453		s2, err := Open(path)
454		if err != nil {
455			t.Fatalf("销毁后的文件应正常重开: %v", err)
456		}
457		p, _ := s2.GetSample("P")
458		if p.Destruction == nil || p.Destruction.Qty != "6.000" {
459			t.Fatalf("重开后销毁量应为真实的 6.000: %+v", p)
460		}
461	}
462	
463	// TestDestroyRejectsInconsistentChildRelationship 销毁不仅核对数量，还要求
464	// 子样列表与来源编号关系一致：旧文件若漏列真正的直接子样、重复列入或列入
465	// 来源不符的样品，即使数量等式碰巧成立，销毁也必须拒绝——否则销毁后的
466	// 文件会在重新打开时因来源关系自相矛盾而失败。拒绝后记录与文件保持原样。
467	func TestDestroyRejectsInconsistentChildRelationship(t *testing.T) {
468		// 漏列：C 的来源指向 P，P 的子样列表为空；剩余 6.000 + C 的 4.000
469		// 数量守恒，但漏列必须拒绝。
470		missing := &ledger{
471			Samples: map[string]*sampleRecord{
472				"P": activeSample("P", "", 10000, 6000),
473				"C": plainChild("C", "P", 4000, 4000),
474			},
475		}
476		s, path := openGapLedger(t, missing)
477		if _, err := s.Destroy(DestroyInput{
478			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
479		}); !errors.Is(err, ErrConflict) {
480			t.Fatalf("漏列直接子样时销毁应 ErrConflict, got %v", err)
481		}
482		assertStillOpenAndUndestroyed(t, path, "P", "6.000", nil)
483	
484		// 重复列入：C 在列表中出现两次（JSON 数组允许重复）。
485		dup := &ledger{
486			Samples: map[string]*sampleRecord{
487				"P": withChild(activeSample("P", "", 10000, 6000), "C", "C"),
488				"C": plainChild("C", "P", 4000, 4000),
489			},
490		}
491		s2, path2 := openGapLedger(t, dup)
492		_, err := s2.Destroy(DestroyInput{
493			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
494		})
495		if !errors.Is(err, ErrConflict) || !strings.Contains(err.Error(), "重复") {
496			t.Fatalf("重复列入子样应 ErrConflict 并说明重复, got %v", err)
497		}
498		assertStillOpenAndUndestroyed(t, path2, "P", "6.000", []string{"C", "C"})
499	
500		// 来源不符：列表列入的 R 是没有来源的原样。
501		wrong := &ledger{
502			Samples: map[string]*sampleRecord{
503				"P": withChild(activeSample("P", "", 10000, 6000), "R"),
504				"R": plainChild("R", "", 4000, 4000),
505			},
506		}
507		s3, path3 := openGapLedger(t, wrong)
508		_, err = s3.Destroy(DestroyInput{
509			SampleID: "P", Operator: "h", Location: "l", At: destroyGapAt, Reason: "r",
510		})
511		if !errors.Is(err, ErrConflict) || !strings.Contains(err.Error(), "R") {
512			t.Fatalf("列入来源不符的样品应 ErrConflict 并指出编号, got %v", err)
513		}
514		assertStillOpenAndUndestroyed(t, path3, "P", "6.000", []string{"R"})
515	}
