103				path := writeStructLedger(t, custodyScenario("李四", location))
104				mustRejectOpen(t, path, "S-001", "销毁地点")
105			})
106		}
107	
108		// 原始文件：没有 location 字段。
109		path := writeRawLedger(t, `{
110			"version": 1,
111			"samples": {"NOLOC": {"id":"NOLOC","initial":5000,"remaining":0,"holder":"李四","location":"实验室B","children":[],"history":[
112				{"kind":"register","time":"2026-10-01T09:00:00Z","holder":"李四","location":"实验室B"},
113				{"kind":"destroy","time":"2026-10-03T12:00:00Z","holder":"李四","location":"实验室B"}
114			],"destroyed":{"operator":"李四","at":"2026-10-03T12:00:00Z","reason":"实验结束按规程销毁","qty":5000}}},
115			"transfers": {}
116		}`)
117		mustRejectOpen(t, path, "NOLOC", "销毁地点")
118	
119		// 销毁地点与样品当前地点同时只有空白：仍属无效，不能视为一致。
120		bothBlank := writeRawLedger(t, `{
121			"version": 1,
122			"samples": {"BOTH": {"id":"BOTH","initial":5000,"remaining":0,"holder":"李四","location":"  ","children":[],"history":[
123				{"kind":"register","time":"2026-10-01T09:00:00Z","holder":"李四","location":"  "},
124				{"kind":"destroy","time":"2026-10-03T12:00:00Z","holder":"李四","location":"  "}
125			],"destroyed":{"operator":"李四","location":"  ","at":"2026-10-03T12:00:00Z","reason":"实验结束按规程销毁","qty":5000}}},
126			"transfers": {}
127		}`)
128		mustRejectOpen(t, bothBlank, "BOTH", "销毁地点")
129	}
130	
131	// TestOpenRejectsDestroyedOperatorWithoutTrimming 两边都有非空文本时按原文
132	// 核对：" 李四 " 与 "李四" 不能通过去掉首尾空白被接受，错误给出两边原值。
133	func TestOpenRejectsDestroyedOperatorWithoutTrimming(t *testing.T) {
134		l := custodyScenario(" 李四 ", "实验室B")
135		path := writeStructLedger(t, l)
136		before, err := os.ReadFile(path)
137		if err != nil {
138			t.Fatal(err)
139		}
140		s, err := Open(path)
141		if err == nil {
142			t.Fatalf("带空白的操作人与持有人原文不同，不应靠去掉空白接受")
143		}
144		if s != nil {
145			t.Fatalf("打开失败时不应返回可用的 Store")
146		}
147		if !errors.Is(err, ErrInvalid) {
148			t.Fatalf("错误应包装 ErrInvalid, got %v", err)
149		}
150		if !strings.Contains(err.Error(), `" 李四 "`) || !strings.Contains(err.Error(), `"李四"`) {
151			t.Fatalf("错误应给出销毁操作人与持有人各自的原文: %v", err)
152		}
153		after, err := os.ReadFile(path)
154		if err != nil {
155			t.Fatal(err)
156		}
157		if string(before) != string(after) {
158			t.Fatalf("打开失败不得改写原文件")
159		}
