161	
162	// TestOpenRejectsDestroyedCustodyDespiteOtherValidSamples 文件中另有完全正常
163	// 的样品时，一处人员/地点矛盾也使整份文件打开失败：不返回 Store、不只加载
164	// 正常部分，原文件保持原样（不补填替换、不删除销毁信息改成未销毁）。
165	func TestOpenRejectsDestroyedCustodyDespiteOtherValidSamples(t *testing.T) {
166		l := custodyScenario("王五", "实验室C")
167		l.Samples["OK"] = destroyedSample("OK", 1000, 0, 1000)
