170	
171		raw := readFileString(t, path)
172		if !strings.Contains(raw, `"destroyed"`) || !strings.Contains(raw, "王五") {
173			t.Fatalf("打开失败不得删除销毁信息或替换操作人: %s", raw)
174		}
