176	
177	// TestOpenDestroyedCustodyCheckedPerSample 核对只针对同一编号样品自身的最后
178	// 记录：父样与子样由不同人员在不同地点分别保管/销毁合法；子样自身销毁
179	// 操作人与它自己的最后持有人不符时，只为子样拒绝整份文件。
180	func TestOpenDestroyedCustodyCheckedPerSample(t *testing.T) {
181		// 父样李四在实验室B销毁；子样已转到王五在实验室C，并由王五在实验室C
182		// 销毁——父子销毁信息互不影响，文件正常恢复。
183		parent := destroyedSample("P", 10000, 0, 7000, "C")
184		child := destroyedSampleWithParent("C", "P", 3000, 3000)
185		child.Holder, child.Location = "王五", "实验室C"
186		child.Destroyed.Operator, child.Destroyed.Location = "王五", "实验室C"
187		good := &ledger{Samples: map[string]*sampleRecord{"P": parent, "C": child}}
188		s, err := Open(writeStructLedger(t, good))
