194		if p.Destruction.Operator != "李四" || p.Destruction.Location != "实验室B" {
195			t.Fatalf("父样销毁详情应原样保留: %+v", p.Destruction)
196		}
197		if p.Holder != "李四" || p.Location != "实验室B" {
198			t.Fatalf("父样最后持有人/地点应保留: %+v", p)
199		}
200		if c.Destruction.Operator != "王五" || c.Destruction.Location != "实验室C" ||
201			c.Holder != "王五" || c.Location != "实验室C" {
202			t.Fatalf("子样销毁详情与最后持有人/地点应保留: %+v", c)
203		}
204	
205		// 子样销毁操作人与其自身最后持有人不符：即使父样记录完全正常，也必须
206		// 拒绝，错误指出有问题的是子样 C 及其操作人，不能拿父样的李四凑一致。
207		badChild := destroyedSampleWithParent("C2", "P2", 3000, 3000)
208		badChild.Holder, badChild.Location = "王五", "实验室C"
209		badChild.Destroyed.Operator, badChild.Destroyed.Location = "赵六", "实验室C"
210		badParent := destroyedSample("P2", 10000, 0, 7000, "C2")
211		bad := &ledger{Samples: map[string]*sampleRecord{"P2": badParent, "C2": badChild}}
212		mustRejectOpen(t, writeStructLedger(t, bad), "C2", "操作人", "赵六", "王五")
213	}
214	
215	// TestOpenDestroyedCustodyIgnoresEarlierHistory 早期登记、交接历史中的人员和
216	// 地点可以与最后记录不同：样品当前持有人李四/实验室B、销毁操作人李四/
217	// 实验室B 时，历史里的张三/实验室A 不构成拒绝理由。
218	func TestOpenDestroyedCustodyIgnoresEarlierHistory(t *testing.T) {
219		rec := destroyedSample("S-001", 10000, 0, 6750, "S-001-A")
220		rec.History = []historyRecord{
221			{Kind: "register", Time: registerCheckAt, Holder: "张三", Location: "实验室A"},
222			{Kind: "transfer-in", Time: registerCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B"},
223			{Kind: "split", Time: splitCheckAt, Holder: "李四", Location: "实验室B"},
224			{Kind: "destroy", Time: destroyedCheckAt, Holder: "李四", Location: "实验室B"},
225		}
226		l := &ledger{
227			Samples: map[string]*sampleRecord{
228				"S-001":   rec,
229				"S-001-A": plainChild("S-001-A", "S-001", 3250, 3250),
230			},
231		}
232		s, err := Open(writeStructLedger(t, l))
233		if err != nil {
234			t.Fatalf("早期历史的人员/地点与最后记录不同不应成为拒绝理由: %v", err)
235		}
236		got, err := s.GetSample("S-001")
237		if err != nil {
238			t.Fatal(err)
239		}
240		if got.Destruction == nil || got.Destruction.Operator != "李四" ||
241			got.Destruction.Location != "实验室B" || got.Destruction.Qty != "6.750" {
242			t.Fatalf("销毁详情应原样保留: %+v", got.Destruction)
243		}
244		if got.Holder != "李四" || got.Location != "实验室B" {
245			t.Fatalf("最后持有人/地点应原样保留: %+v", got)
246		}
247	}
248	
249	// TestOpenRestoresConsistentDestroyedCustody 信息一致且通过原有数量、时间
250	// 检查的记录正常打开，查询仍保留原销毁详情和最后持有人、地点。
251	func TestOpenRestoresConsistentDestroyedCustody(t *testing.T) {
252		path := writeStructLedger(t, custodyScenario("李四", "实验室B"))
253		s, err := Open(path)
254		if err != nil {
255			t.Fatalf("销毁操作人/地点与最后持有人/地点一致应正常恢复: %v", err)
256		}
257		got, err := s.GetSample("S-001")
258		if err != nil {
259			t.Fatal(err)
260		}
261		if got.Destruction == nil {
262			t.Fatalf("销毁详情应保留")
263		}
264		if got.Destruction.Operator != "李四" || got.Destruction.Location != "实验室B" ||
265			got.Destruction.Qty != "6.750" {
266			t.Fatalf("销毁详情应按原文保留: %+v", got.Destruction)
267		}
268		if got.Holder != "李四" || got.Location != "实验室B" || got.Remaining != "0.000" {
269			t.Fatalf("最后持有人/地点与数量应按原文保留: %+v", got)
270		}
271	}
