169	
170		// --- 场景一：合计超过 9223372036854775.807 的支持上限 ---------------
171		// 两个子样数量分别合法（一个取上限本身，一个取最小合法量），但合计
172		// 超过上限一个最小刻度，int64 累加会回绕；必须判为 ErrInvalid，
173		// 不能把合计误判成一个更小的合法数量而放行。
174		mustRegister(t, s, "BIG", maxQtyString, "张三", "实验室A")
175		bigBefore, err := s.GetSample("BIG")
176		if err != nil {
