180			{ID: "OVF1", Qty: maxQtyString}, // 上限本身，单独合法
181			{ID: "OVF2", Qty: "0.001"},      // 最小合法量，合计 = 上限 + 0.001
182		}})
183		if !errors.Is(err, ErrInvalid) {
184			t.Fatalf("合计超出支持范围应返回 ErrInvalid, got %v", err)
185		}
186		if errors.Is(err, ErrConflict) {
187			t.Fatalf("超出表示范围不能按普通超量处理为 ErrConflict, got %v", err)
188		}
189		if !strings.Contains(err.Error(), "超出可表示范围") {
190			t.Fatalf("错误内容应能看出是合计超出表示范围, got %v", err)
191		}
192	
193		// 被拒绝后来源数量、子样编号、保管历史、持有人地点与待确认状态全部不变。
194		bigAfter, err := s.GetSample("BIG")
195		if err != nil {
