197		}
198		if !reflect.DeepEqual(bigAfter, bigBefore) {
199			t.Fatalf("被拒绝分装改动了来源状态:\n before=%+v\n after =%+v", bigBefore, bigAfter)
200		}
201		if bigAfter.Remaining != maxQtyString || bigAfter.InitialQty != maxQtyString {
202			t.Fatalf("被拒绝分装不得扣减来源数量: init=%s remaining=%s",
203				bigAfter.InitialQty, bigAfter.Remaining)
204		}
205		if len(bigAfter.Children) != 0 || len(bigAfter.History) != 1 {
206			t.Fatalf("被拒绝分装不得追加子样编号或保管历史: %+v", bigAfter)
207		}
208		if bigAfter.Holder != "张三" || bigAfter.Location != "实验室A" ||
209			bigAfter.PendingTransfer != nil || bigAfter.Destruction != nil {
210			t.Fatalf("被拒绝分装不得改变持有人、地点及待确认状态: %+v", bigAfter)
211		}
212		for _, id := range []string{"OVF1", "OVF2"} {
213			if got, err := s.GetSample(id); !errors.Is(err, ErrNotFound) {
214				t.Fatalf("被拒绝批次的子样 %s 应查不到, got view=%+v err=%v", id, got, err)
215			}
216		}
217	
218		// --- 场景二：合计仍在支持范围内，但比来源剩余量多 0.001 -------------
219		// 来源初始为上限 - 0.001，先成功分出 0.001（来源剩上限 - 0.002），
220		// 制造拒绝前已存在的子样和保管历史。
221		mustRegister(t, s, "NEAR", belowMaxString, "张三", "实验室A")
222		if _, err := s.Split(SplitInput{ParentID: "NEAR", Parts: []SplitPart{
223			{ID: "E0", Qty: "0.001"},
224		}}); err != nil {
225			t.Fatalf("前置小分装应成功: %v", err)
226		}
227		nearBefore, err := s.GetSample("NEAR")
228		if err != nil {
229			t.Fatal(err)
230		}
231		if nearBefore.Remaining != twoBelowString {
232			t.Fatalf("前置分装后来源应剩余 %s, got %s", twoBelowString, nearBefore.Remaining)
233		}
234	
235		// (上限 - 0.003) + 0.002 = 上限 - 0.001，合计未超支持范围，
236		// 但比来源剩余量（上限 - 0.002）恰好多 0.001。
237		_, err = s.Split(SplitInput{ParentID: "NEAR", Parts: []SplitPart{
238			{ID: "OVR1", Qty: threeBelowStr}, // 上限 - 0.003，单独合法
239			{ID: "OVR2", Qty: "0.002"},       // 合计 上限 - 0.001 <= 上限
240		}})
241		if !errors.Is(err, ErrConflict) {
242			t.Fatalf("合计超过来源剩余量应返回 ErrConflict, got %v", err)
243		}
244		if !strings.Contains(err.Error(), "超过") || !strings.Contains(err.Error(), "剩余量") {
245			t.Fatalf("错误内容应能看出是合计超过来源剩余量, got %v", err)
246		}
247	
248		// 来源数量、子样列表与历史保持在拒绝前；待确认/销毁状态不变。
249		nearAfter, err := s.GetSample("NEAR")
250		if err != nil {
251			t.Fatal(err)
252		}
253		if nearAfter.InitialQty != belowMaxString || nearAfter.Remaining != twoBelowString {
254			t.Fatalf("被拒绝分装不得扣减来源数量: init=%s remaining=%s",
255				nearAfter.InitialQty, nearAfter.Remaining)
256		}
257		if len(nearAfter.Children) != 1 || nearAfter.Children[0] != "E0" {
258			t.Fatalf("拒绝前已存在的子样列表应原样保留: %v", nearAfter.Children)
259		}
260		if len(nearAfter.History) != 2 ||
261			nearAfter.History[0].Kind != "register" || nearAfter.History[1].Kind != "split" {
262			t.Fatalf("拒绝前已存在的保管历史应继续保留: %+v", nearAfter.History)
263		}
264		if nearAfter.Holder != "张三" || nearAfter.Location != "实验室A" ||
265			nearAfter.PendingTransfer != nil || nearAfter.Destruction != nil {
266			t.Fatalf("被拒绝分装不得改变持有人、地点及待确认状态: %+v", nearAfter)
267		}
268	
269		// 拒绝前已经存在的子样继续保留且数量不变；本次拟创建的子样仍查不到。
270		e0, err := s.GetSample("E0")
271		if err != nil {
272			t.Fatalf("拒绝前已存在的子样应继续可查: %v", err)
273		}
274		if e0.InitialQty != "0.001" || e0.Remaining != "0.001" || e0.ParentID != "NEAR" {
275			t.Fatalf("拒绝前已存在的子样状态被改动: %+v", e0)
276		}
277		for _, id := range []string{"OVR1", "OVR2"} {
278			if got, err := s.GetSample(id); !errors.Is(err, ErrNotFound) {
279				t.Fatalf("被拒绝批次的子样 %s 应查不到, got view=%+v err=%v", id, got, err)
280			}
281		}
282	}
