9	// 重新打开数据时，每份未销毁样品（原样与分装子样）的自身数量必须自洽：
10	// 初始量大于零，剩余量可为零但不能为负、也不能超过自身初始量。这些测试
11	// 构造公开操作无法产生的损坏记录，验证 Open 一律拒绝、整份文件不加载、
12	// 原文件不改写，且错误可用 errors.Is 判定为 ErrInvalid。
13	
14	// activeSample 构造一份未销毁样品记录，数量单位均为千分之一毫升。
15	func activeSample(id string, parent string, initial, remaining int64) *sampleRecord {
16		s := &sampleRecord{
17			ID:        id,
18			ParentID:  parent,
19			Initial:   initial,
20			Remaining: remaining,
21			Holder:    "h",
22			Location:  "l",
23			Children:  []string{},
24			History: []historyRecord{{
25				Kind: "register", Time: time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC),
26				Holder: "h", Location: "l",
27			}},
28		}
29		if parent != "" {
30			s.History[0].Kind = "split"
31		}
32		return s
33	}
34	
35	// TestOpenRejectsRemainingAboveInitial 任务示例：初始量 10.000 毫升，剩余量
36	// 却被写成 12.000 毫升。没有销毁信息也必须拒绝，不能让多出的剩余量继续
37	// 参与分装。
38	func TestOpenRejectsRemainingAboveInitial(t *testing.T) {
39		l := &ledger{
40			Samples: map[string]*sampleRecord{
41				"S-001": activeSample("S-001", "", 10000, 12000),
42			},
43		}
44		path := writeStructLedger(t, l)
45		mustRejectOpen(t, path, "S-001", "12.000", "10.000", "超过自身初始量")
46	}
47	
48	// TestOpenRejectsChildRemainingAboveOwnInitial 子样的上限是它自己创建时取
49	// 得的初始量：子样自身初始 3.000、剩余 3.500 时拒绝，不能借用父样的量。
50	func TestOpenRejectsChildRemainingAboveOwnInitial(t *testing.T) {
51		l := &ledger{
52			Samples: map[string]*sampleRecord{
53				"P": activeSample("P", "", 10000, 7000),
54				"C": plainChild("C", "P", 3000, 3500),
55			},
56		}
57		path := writeStructLedger(t, l)
58		mustRejectOpen(t, path, "C", "3.500", "3.000", "超过自身初始量")
59	}
60	
61	// TestOpenRejectsNegativeRemaining 未销毁样品剩余量为负必须拒绝，错误以
62	// 三位小数毫升展示负值。
63	func TestOpenRejectsNegativeRemaining(t *testing.T) {
64		cases := []struct {
65			name      string
66			remaining int64
67			text      string
68		}{
69			{"负一个最小刻度", -1, "-0.001"},
70			{"负一毫升", -1000, "-1.000"},
71			{"极端负数量", math.MinInt64, "-9223372036854775.808"},
72		}
73		for _, c := range cases {
74			t.Run(c.name, func(t *testing.T) {
75				l := &ledger{
76					Samples: map[string]*sampleRecord{
77						"S1": activeSample("S1", "", 10000, c.remaining),
78					},
79				}
80				path := writeStructLedger(t, l)
81				mustRejectOpen(t, path, "S1", c.text, "10.000", "不能为负")
82			})
83		}
84	}
85	
86	// TestOpenRejectsNonPositiveInitialOnActiveSample 未销毁样品初始量必须大于
87	// 零，零初始量与负初始量都要拒绝（原样、子样一致）。
88	func TestOpenRejectsNonPositiveInitialOnActiveSample(t *testing.T) {
89		cases := []struct {
90			name    string
91			parent  string
92			initial int64
93			text    string
94		}{
95			{"原样初始量为零", "", 0, "0.000"},
96			{"原样初始量为负", "", -5000, "-5.000"},
97			{"子样初始量为零", "P", 0, "0.000"},
98			{"子样初始量为负", "P", -1, "-0.001"},
99		}
100		for _, c := range cases {
101			t.Run(c.name, func(t *testing.T) {
102				samples := map[string]*sampleRecord{
103					"BAD": activeSample("BAD", c.parent, c.initial, 0),
104				}
105				if c.parent != "" {
106					samples["P"] = activeSample("P", "", 10000, 10000)
107				}
108				l := &ledger{Samples: samples}
109				path := writeStructLedger(t, l)
110				mustRejectOpen(t, path, "BAD", c.text, "初始量", "大于零")
111			})
112		}
113	}
114	
115	// TestOpenRejectsOverrunEvenWhenPendingTransferMatches 待确认交接不影响数量
116	// 检查：交接量、交出人、地点都与错误的剩余量 12.000 一致时，数量越界仍
117	// 必须先按数量规则拒绝，不能被交接关联检查接受。
118	func TestOpenRejectsOverrunEvenWhenPendingTransferMatches(t *testing.T) {
119		sample := activeSample("S1", "", 10000, 12000)
120		sample.PendingID = "T1"
121		l := &ledger{
122			Samples: map[string]*sampleRecord{"S1": sample},
123			Transfers: map[string]*transferRecord{
124				"T1": {
125					ID: "T1", SampleID: "S1",
126					FromHolder: "h", FromLocation: "l",
127					ToHolder: "x", ToLocation: "y",
128					Qty:          12000,
129					HandedOverAt: time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC),
130					Confirmed:    false,
131				},
132			},
133		}
134		path := writeStructLedger(t, l)
135		mustRejectOpen(t, path, "S1", "12.000", "10.000", "超过自身初始量")
136	}
137	
138	// TestOpenActiveQuantityCheckIsWholeFileFailure 一份记录数量越界时整份文件
139	// 打开失败，不能只加载其他正常样品。
140	func TestOpenActiveQuantityCheckIsWholeFileFailure(t *testing.T) {
141		l := &ledger{
142			Samples: map[string]*sampleRecord{
143				"OK":  activeSample("OK", "", 1000, 1000),
144				"BAD": activeSample("BAD", "", 1000, 2000),
145			},
146		}
147		path := writeStructLedger(t, l)
148		mustRejectOpen(t, path, "BAD", "2.000", "1.000")
149	}
