151	// TestOpenAcceptsActiveQuantityBoundaries 数量边界的合法记录不能被误拒：
152	// 剩余量等于初始量（满量）、等于零（旧数据分装用尽、无销毁信息、无子样）
153	// 都按原约定加载；支持上限附近的大数量也逐位准确。
154	func TestOpenAcceptsActiveQuantityBoundaries(t *testing.T) {
155		cases := []struct {
156			name              string
157			id                string
158			initial, remain   int64
159			wantInit, wantRem string
160		}{
161			{"满量", "FULL", 10000, 10000, "10.000", "10.000"},
162			{"零剩余量旧记录", "ZERO", 1000, 0, "1.000", "0.000"},
163			{"最小正数量", "MIN", 1, 1, "0.001", "0.001"},
164			{"上限附近", "BIG", math.MaxInt64, math.MaxInt64, maxQtyString, maxQtyString},
165			{"上限附近零剩余", "BIG0", math.MaxInt64, 0, maxQtyString, "0.000"},
166		}
167		for _, c := range cases {
168			t.Run(c.name, func(t *testing.T) {
169				l := &ledger{
170					Samples: map[string]*sampleRecord{
171						c.id: activeSample(c.id, "", c.initial, c.remain),
172					},
173				}
174				s, err := Open(writeStructLedger(t, l))
175				if err != nil {
176					t.Fatalf("数量在合法边界内应正常恢复: %v", err)
177				}
178				got, err := s.GetSample(c.id)
179				if err != nil {
180					t.Fatal(err)
181				}
182				if got.InitialQty != c.wantInit || got.Remaining != c.wantRem {
183					t.Fatalf("数量恢复错误: init=%s want=%s remaining=%s want=%s",
184						got.InitialQty, c.wantInit, got.Remaining, c.wantRem)
185				}
186				if got.Destruction != nil {
187					t.Fatalf("无销毁信息的记录不能补出销毁记录: %+v", got.Destruction)
188				}
189			})
190		}
191	}
192	
193	// TestFormatUnitsHandlesNegatives 负数数量只出现在损坏数据的错误说明中，
194	// 必须稳定渲染，尤其 math.MinInt64 不能因取负回绕而异常或不返回。
195	func TestFormatUnitsHandlesNegatives(t *testing.T) {
196		cases := []struct {
197			units int64
198			want  string
199		}{
200			{0, "0.000"},
201			{1, "0.001"},
202			{1000, "1.000"},
203			{-1, "-0.001"},
204			{-1000, "-1.000"},
205			{-1001, "-1.001"},
206			{-1234, "-1.234"},
207			{math.MaxInt64, "9223372036854775.807"},
208			{math.MinInt64, "-9223372036854775.808"},
209		}
210		for _, c := range cases {
211			if got := formatUnits(c.units); got != c.want {
212				t.Fatalf("formatUnits(%d) = %q, want %q", c.units, got, c.want)
213			}
214		}
215	}
