227	// TestOpenDistributionIgnoresGrandchildrenAndOtherRoots 祖父样的核对只认
228	// 来源编号直接指向它的子样：孙样 G（来源为 C）与另一份原样 R、R 的子样
229	// 都不计入 P 的合计。
230	func TestOpenDistributionIgnoresGrandchildrenAndOtherRoots(t *testing.T) {
231		l := &ledger{
232			Samples: map[string]*sampleRecord{
233				// P: 6.000 + 直接子样 C 初始 4.000 = 10.000 合法；若错误地把
234				// 孙样 G 的 4.000 或 R-D 计入就会得到 14.000/11.000 而误拒。
235				"P":   withChild(activeSample("P", "", 10000, 6000), "C"),
236				"C":   withChild(plainChild("C", "P", 4000, 0), "G"),
237				"G":   plainChild("G", "C", 4000, 4000),
238				"R":   withChild(activeSample("R", "", 8000, 1000), "R-D"),
239				"R-D": plainChild("R-D", "R", 7000, 7000),
240			},
241		}
242		if _, err := Open(writeStructLedger(t, l)); err != nil {
243			t.Fatalf("孙样、其他原样及其子样都不应参与 P 的核对: %v", err)
244		}
245	}
246	
247	// TestOpenAcceptsUnlistedChildWhenTotalsConsistent 子样列表漏列时，未销毁
248	// 样品不做来源关系一致性拒绝，但漏列的子样仍按来源编号计入：合计不超量
249	// 时文件照常恢复（关系列表原样保留，不替它补列）。
250	func TestOpenAcceptsUnlistedChildWhenTotalsConsistent(t *testing.T) {
251		parent := activeSample("P", "", 10000, 6000)
252		parent.Children = []string{}
253		l := &ledger{
254			Samples: map[string]*sampleRecord{
255				"P": parent,
256				"C": plainChild("C", "P", 4000, 4000),
257			},
258		}
259		s, err := Open(writeStructLedger(t, l))
260		if err != nil {
261			t.Fatalf("漏列子样但合计恰好等于初始量时应正常恢复: %v", err)
262		}
263		p, _ := s.GetSample("P")
264		if len(p.Children) != 0 {
265			t.Fatalf("恢复流程不得替旧数据补列子样: %v", p.Children)
266		}
267	}
268	
269	// TestOpenActiveDistributionLargeBounds 大数量边界：上限附近的合法合计
270	// （剩余 0.001 + 直接子样 上限-0.001 = 上限）必须逐位准确接受；合计超出
271	// int64 支持范围（剩余取上限、另有正量子样）时明确按超出支持范围拒绝，
272	// 不能接受回绕后的结果。
273	func TestOpenActiveDistributionLargeBounds(t *testing.T) {
274		const (
275			maxUnits   int64 = math.MaxInt64
276			belowUnits int64 = math.MaxInt64 - 1
277		)
278		legal := &ledger{
279			Samples: map[string]*sampleRecord{
280				"BIG": withChild(activeSample("BIG", "", maxUnits, 1), "BIG-C"),
281				"BIG-C": func() *sampleRecord {
282					c := plainChild("BIG-C", "BIG", belowUnits, belowUnits)
283					return c
284				}(),
285			},
286		}
287		s, err := Open(writeStructLedger(t, legal))
288		if err != nil {
289			t.Fatalf("上限附近的合法合计应准确恢复: %v", err)
290		}
291		big, _ := s.GetSample("BIG")
292		if big.InitialQty != maxQtyString || big.Remaining != "0.001" {
293			t.Fatalf("上限父样恢复不精确: %+v", big)
294		}
295		bigC, _ := s.GetSample("BIG-C")
296		if bigC.InitialQty != belowMaxString {
297			t.Fatalf("上限附近子样恢复不精确: %s", bigC.InitialQty)
298		}
299	
300		overflow := &ledger{
301			Samples: map[string]*sampleRecord{
302				"BIG":   withChild(activeSample("BIG", "", maxUnits, maxUnits), "BIG-C"),
303				"BIG-C": plainChild("BIG-C", "BIG", 1, 1),
304			},
305		}
306		mustRejectOpen(t, writeStructLedger(t, overflow), "BIG", "超出可表示范围")
307	}
308

