356	// 时的初始量：
357	//   - 孙样不重复计入：父样分出 4.000 给子样，子样又把 4.000 全部分给孙样，
358	//     父样销毁 6.000 仍满足 6.000 + 4.000 = 10.000；
359	//   - 子样后来继续分装、转交或销毁不改变父样已分出的量：子样当前只剩
360	//     2.250（自身又分出 1.000）或已全部销毁，父样仍按子样初始量 3.250 核
361	//     对，不能改用子样当前剩余量。
362	func TestOpenDestroyedAccountingUsesChildInitialOnly(t *testing.T) {
363		// 场景一：孙样不重复计入；子样分装用尽（无销毁信息）也合法。
364		grandchild := plainChild("G", "C", 4000, 4000)
365		childExhausted := plainChild("C", "P", 4000, 0)
366		childExhausted.Children = []string{"G"}
367		childExhausted.History = append(childExhausted.History, historyRecord{
368			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
369		})
370		l1 := &ledger{
371			Samples: map[string]*sampleRecord{
372				"P": destroyedSample("P", 10000, 0, 6000, "C"),
373				"C": childExhausted,
374				"G": grandchild,
375			},
376		}
377		if s, err := Open(writeStructLedger(t, l1)); err != nil {
378			t.Fatalf("孙样不得计入父样销毁核对，6.000+4.000=10.000 应恢复: %v", err)
379		} else {
380			p, _ := s.GetSample("P")
381			if p.Destruction == nil || p.Destruction.Qty != "6.000" {
382				t.Fatalf("父样销毁量恢复错误: %+v", p.Destruction)
383			}
384		}
385	
386		// 场景二：子样自己又分出 1.000，当前只剩 2.250；父样仍按子样初始量
387		// 3.250 核对（6.750 + 3.250 = 10.000）。
388		childSplit := plainChild("S-001-A", "S-001", 3250, 2250)
389		childSplit.Children = []string{"S-001-A-G"}
390		childSplit.History = append(childSplit.History, historyRecord{
391			Kind: "split", Time: splitCheckAt.Add(time.Hour), Holder: "李四", Location: "实验室B",
392		})
393		l2 := &ledger{
394			Samples: map[string]*sampleRecord{
