474	// TestOpenDestroyedAtLargeBounds 大数量边界：支持上限附近的合法销毁记录
475	// 必须逐位准确恢复；销毁量与直接子样初始量合计超出 int64 支持范围时按
476	// 无效数据拒绝，不能因数量过大忽略差额或接受回绕后的错误等式。
477	func TestOpenDestroyedAtLargeBounds(t *testing.T) {
478		const (
479			maxUnits   int64 = 9223372036854775807 // 9223372036854775.807 毫升
480			belowUnits int64 = 9223372036854775806 // 9223372036854775.806 毫升
481		)
482	
483		// 合法：初始量取上限，分出上限-0.001 的直接子样，销毁最后的 0.001，
484		// 合计恰好等于上限，重开后三位小数逐位一致。
485		legal := &ledger{
486			Samples: map[string]*sampleRecord{
487				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "BIG-C"),
488				"BIG-C": func() *sampleRecord {
489					c := plainChild("BIG-C", "BIG", belowUnits, belowUnits)
490					return c
491				}(),
492			},
493		}
494		s, err := Open(writeStructLedger(t, legal))
495		if err != nil {
496			t.Fatalf("上限附近的合法销毁记录应准确恢复: %v", err)
497		}
498		big, _ := s.GetSample("BIG")
499		if big.InitialQty != maxQtyString || big.Remaining != "0.000" ||
500			big.Destruction == nil || big.Destruction.Qty != "0.001" {
501			t.Fatalf("上限父样恢复不精确: %+v", big)
502		}
503		bigC, _ := s.GetSample("BIG-C")
504		if bigC.InitialQty != belowMaxString || bigC.Remaining != belowMaxString {
505			t.Fatalf("上限附近子样恢复不精确: init=%s remaining=%s",
506				bigC.InitialQty, bigC.Remaining)
507		}
508	
509		// 溢出场景一：销毁量 + 直接子样初始量在上限之外一个最小刻度
510		//（子样 上限-0.001，销毁 0.002：合计 上限+0.001），最终求和溢出，
511		// 必须按超出支持范围拒绝。
512		overflowFinal := &ledger{
513			Samples: map[string]*sampleRecord{
514				"BIG":   destroyedSample("BIG", maxUnits, 0, 2, "BIG-C"),
515				"BIG-C": plainChild("BIG-C", "BIG", belowUnits, belowUnits),
516			},
517		}
518		mustRejectOpen(t, writeStructLedger(t, overflowFinal), "BIG", "超出可表示范围")
519	
520		// 溢出场景二：各直接子样初始量累加本身溢出（子样合计超过上限），
521		// 在统计直接子样总量时即拒绝，不能回绕成一个小数量再去凑等式。
522		overflowChildren := &ledger{
523			Samples: map[string]*sampleRecord{
524				"BIG": destroyedSample("BIG", maxUnits, 0, 1, "C1", "C2"),
525				"C1":  plainChild("C1", "BIG", belowUnits, belowUnits),
526				"C2":  plainChild("C2", "BIG", 2, 2),
527			},
528		}
529		mustRejectOpen(t, writeStructLedger(t, overflowChildren), "BIG", "超出可表示范围")
530	}
531	
532	// TestOpenLegacySamplesWithoutDestructionUnaffected 没有销毁信息的旧样品
533	// 继续按现有规则恢复：无论剩余量是否为零都不参与销毁数量核对，也不能据
534	// 剩余量为零补出销毁记录。
535	func TestOpenLegacySamplesWithoutDestructionUnaffected(t *testing.T) {
536		// 旧样品分装用尽、剩余量为零、无销毁信息；另带一个正常有量旧样品。
537		exhausted := plainChild("OLD", "", 10000, 0)
538		exhausted.ParentID = ""
539		exhausted.Children = []string{"OLD-C"}
540		exhausted.History = []historyRecord{{
541			Kind: "register", Time: registerCheckAt, Holder: "h", Location: "l",
542		}, {
543			Kind: "split", Time: splitCheckAt, Holder: "h", Location: "l",
544		}}
545		exhausted.Holder, exhausted.Location = "h", "l"
546		child := plainChild("OLD-C", "OLD", 10000, 10000)
547		fresh := &sampleRecord{
548			ID: "NEW", Initial: 5000, Remaining: 5000, Holder: "h", Location: "l",
549			Children: []string{},
550			History: []historyRecord{{
551				Kind: "register", Time: registerCheckAt, Holder: "h", Location: "l",
552			}},
553		}
554		l := &ledger{
555			Samples: map[string]*sampleRecord{
556				"OLD":   exhausted,
557				"OLD-C": child,
558				"NEW":   fresh,
559			},
560		}
561		s, err := Open(writeStructLedger(t, l))
562		if err != nil {
563			t.Fatalf("无销毁信息的旧样品应按原规则恢复，不做销毁数量核对: %v", err)
564		}
565		old, _ := s.GetSample("OLD")
566		if old.Remaining != "0.000" || old.Destruction != nil {
567			t.Fatalf("旧样品剩余为零也不能补出销毁记录: %+v", old)
568		}
569		newSample, _ := s.GetSample("NEW")
570		if newSample.Destruction != nil || newSample.Remaining != "5.000" {
571			t.Fatalf("正常旧样品不应受新核对影响: %+v", newSample)
572		}
573	}
574	
575	// TestOpenRestoresParentAndChildDestructionViaAPI 端到端：通过公开操作产生
576	// 父子各自销毁的合法文件，重开后两份销毁记录独立保留，来源、人员、地点、
577	// 保管历史与销毁量都可查询，且恢复后操作限制与幂等行为保持兼容。
578	func TestOpenRestoresParentAndChildDestructionViaAPI(t *testing.T) {
579		dir := t.TempDir()
580		path := filepath.Join(dir, "data.json")
581		s, err := Open(path)
582		if err != nil {
583			t.Fatal(err)
584		}
585		s.now = func() time.Time { return registerCheckAt }
586		mustRegister(t, s, "P", "10.000", "张三", "A")
587		if _, err := s.Split(SplitInput{ParentID: "P", Parts: []SplitPart{
588			{ID: "C", Qty: "3.250"},
589		}}); err != nil {
590			t.Fatal(err)
591		}
592		parentAt := time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
593		if _, err := s.Destroy(DestroyInput{
594			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
595		}); err != nil {
596			t.Fatalf("销毁父样剩余 6.750: %v", err)
597		}
598		childAt := parentAt.Add(time.Hour)
599		if _, err := s.Destroy(DestroyInput{
600			SampleID: "C", Operator: "张三", Location: "A", At: childAt, Reason: "子样销毁",
601		}); err != nil {
602			t.Fatalf("销毁子样全部 3.250: %v", err)
603		}
604	
605		s2, err := Open(path)
606		if err != nil {
607			t.Fatalf("父子各自销毁的合法文件应正常恢复: %v", err)
608		}
609		p, err := s2.GetSample("P")
610		if err != nil {
611			t.Fatal(err)
612		}
613		c, err := s2.GetSample("C")
614		if err != nil {
615			t.Fatal(err)
616		}
617		if p.InitialQty != "10.000" || p.Remaining != "0.000" ||
618			p.Destruction == nil || p.Destruction.Qty != "6.750" ||
619			p.Destruction.Operator != "张三" || p.Destruction.Location != "A" ||
620			p.Destruction.Reason != "原样销毁" || !p.Destruction.At.Equal(parentAt) {
621			t.Fatalf("父样销毁记录恢复错误: %+v", p)
622		}
623		if len(p.Children) != 1 || p.Children[0] != "C" {
624			t.Fatalf("父样来源/子样关系应保留: %+v", p.Children)
625		}
626		if c.ParentID != "P" || c.InitialQty != "3.250" || c.Remaining != "0.000" ||
627			c.Destruction == nil || c.Destruction.Qty != "3.250" ||
628			c.Destruction.Reason != "子样销毁" || !c.Destruction.At.Equal(childAt) {
629			t.Fatalf("子样销毁记录恢复错误: %+v", c)
630		}
631	
632		// 恢复后销毁幂等与操作限制继续生效。
633		if _, err := s2.Destroy(DestroyInput{
634			SampleID: "P", Operator: "张三", Location: "A", At: parentAt, Reason: "原样销毁",
635		}); err != nil {
636			t.Fatalf("恢复后相同销毁请求应幂等返回: %v", err)
637		}
638		if _, err := s2.Split(SplitInput{ParentID: "P", Parts: []SplitPart{{ID: "X", Qty: "0.001"}}}); !errors.Is(err, ErrConflict) {
639			t.Fatalf("恢复后已销毁父样仍不得分装, got %v", err)
640		}
641		if _, err := s2.Handover(HandoverInput{
642			TransferID: "T-X", SampleID: "C",
643			FromHolder: "张三", FromLocation: "A",
644			ToHolder: "李四", ToLocation: "B", HandedOverAt: childAt.Add(time.Hour),
645		}); !errors.Is(err, ErrConflict) {
646			t.Fatalf("恢复后已销毁子样仍不得发起交接, got %v", err)
647		}
648	
649		// 原始文件没有被恢复流程改写（仍为最后一次成功操作落盘的内容，
650		// 重新打开前后再次读取一致）。
651		raw, err := os.ReadFile(path)
652		if err != nil {
653			t.Fatal(err)
654		}
655		if !strings.Contains(string(raw), `"qty": 6750`) || !strings.Contains(string(raw), `"qty": 3250`) {
656			t.Fatalf("落盘文件应原样保留两份销毁量: %s", string(raw))
657		}
658	}
